<script setup lang="ts">import {onMounted,ref} from 'vue'; import type {OpsBridgeAuth} from '../../../packages/auth-client/src/index'; const props=defineProps<{auth:OpsBridgeAuth}>(); const api=import.meta.env.VITE_API_URL??'http://localhost:8080/api/v1'; const connectors=ref([{name:'Stripe',category:'Billing',state:'Sandbox ready',color:'#635bff'},{name:'Google Drive',category:'Documents',state:'Not connected',color:'#4285f4'},{name:'Microsoft Graph',category:'Productivity',state:'Not connected',color:'#d83b01'},{name:'WhatsApp',category:'Messaging',state:'Not connected',color:'#25d366'},{name:'DocuSign',category:'E-signature',state:'Not connected',color:'#ffcc00'},{name:'Vapi',category:'Voice AI',state:'Not connected',color:'#7656d6'},{name:'Vodex',category:'Voice AI',state:'Not connected',color:'#6f43a8'}]); const notice=ref(''); const colors:any={'stripe':'#635bff','google-drive':'#4285f4','microsoft-graph':'#d83b01','whatsapp':'#25d366','docusign':'#ffcc00','vapi':'#7656d6','vodex':'#6f43a8'}; onMounted(async()=>{try{const r=await fetch(`${api}/integrations`,{headers:await props.auth.headers()});const data=await r.json();if(r.ok&&data.items)connectors.value=data.items.map((item:any)=>({name:item.id.split('-').map((v:string)=>v[0].toUpperCase()+v.slice(1)).join(' '),category:item.id==='stripe'?'Billing':'Connected service',state:item.configured?'Configured':'Needs credentials',color:colors[item.id]??'#648171'}))}catch{notice.value='Could not load server-side connector configuration.'}}); async function connect(c:any){if(c.name==='Stripe'){try{const r=await fetch(`${api}/billing/checkout`,{method:'POST',headers:{'Content-Type':'application/json',...await props.auth.headers()},body:JSON.stringify({successUrl:location.href,cancelUrl:location.href})});const d=await r.json();if(d.url)location.href=d.url;else notice.value=d.message??d.error??'Configure Stripe sandbox credentials in the backend.'}catch{notice.value='Billing service is unavailable. Start the local backend.'}}else notice.value=`${c.name} needs its OAuth or sandbox credentials configured server-side. Provider tokens are not stored in this browser.`}</script>
<template><div class="app"><aside><h2><i>O</i> opsbridge</h2><p>BUILD</p><a>Overview</a><a>Workflow templates</a><a class="on">Integrations</a><a>API keys</a><div class="tenant">{{props.auth.displayName}}<br><b>Workspace admin</b></div></aside><main><small>PLATFORM / CONNECTORS</small><h1>Integrations</h1><p class="intro">Connect the systems your operational workflows depend on.</p><button v-if="props.auth.enabled" class="signout" @click="props.auth.logout()">Sign out</button><div v-if="notice" class="notice">{{notice}}</div><section><div v-for="c in connectors" :key="c.name" class="connector"><div class="logo" :style="{'--brand':c.color}">{{c.name.slice(0,1)}}</div><div class="info"><b>{{c.name}}</b><small>{{c.category}}</small></div><span :class="['status',c.state==='Configured'?'ready':'']">{{c.state}}</span><button @click="connect(c)">{{c.name==='Stripe'?'Open billing':'Configure'}}</button></div></section><footer>Connector credentials are stored server-side using the configured secrets backend.</footer></main></div></template>
